 1→import { useEffect, useRef, useState } from 'react';
 2→import embed from 'vega-embed';
 3→import { useTheme } from '../hooks/useTheme';
 4→import { useTranslation } from '../hooks/useTranslation';
 5→
 6→interface VegaLiteChartWidgetProps {
 7→  spec: Record<string, unknown>;
 8→}
 9→
10→export function VegaLiteChartWidget({ spec }: VegaLiteChartWidgetProps) {
11→  const containerRef = useRef<HTMLDivElement>(null);
12→  const viewRef = useRef<{ finalize: () => void } | null>(null);
13→  const { theme } = useTheme();
14→  const isDark = theme === 'dark';
15→  const { t } = useTranslation();
16→  const [error, setError] = useState<string | null>(null);
17→
18→  useEffect(() => {
19→    if (!containerRef.current || !spec) return;
20→
21→    setError(null);
22→    viewRef.current?.finalize();
23→    viewRef.current = null;
24→
25→    const darkConfig = {
26→      background: 'transparent',
27→      axis: {
28→        labelColor: '#e2e8f0',
29→        titleColor: '#e2e8f0',
30→        gridColor: '#374151',
31→        domainColor: '#374151',
32→      },
33→      legend: {
34→        labelColor: '#e2e8f0',
35→        titleColor: '#e2e8f0',
36→      },
37→      title: {
38→        color: '#e2e8f0',
39→      },
40→      view: {
41→        stroke: 'transparent',
42→      },
43→    };
44→
45→    const lightConfig = {
46→      background: 'transparent',
47→      view: {
48→        stroke: 'transparent',
49→      },
50→    };
51→
52→    const fullSpec = {
53→      ...spec,
54→      width: 'container',
55→      autosize: { type: 'fit', contains: 'padding' },
56→      config: isDark ? darkConfig : lightConfig,
57→    };
58→
59→    let cancelled = false;
60→    embed(containerRef.current, fullSpec as never, {
61→      actions: true,
62→      renderer: 'svg',
63→    })
64→      .then((result) => {
65→        if (cancelled) {
66→          result.finalize();
67→        } else {
68→          viewRef.current = result;
69→        }
70→      })
71→      .catch((err) => {
72→        if (!cancelled) {
73→          setError(err?.message || 'Failed to render Vega-Lite chart');
74→        }
75→      });
76→
77→    return () => {
78→      cancelled = true;
79→      viewRef.current?.finalize();
80→      viewRef.current = null;
81→    };
82→  }, [spec, isDark]);
83→
84→  if (error) {
85→    return (
86→      <div style={{ padding: '1rem', textAlign: 'center', opacity: 0.6 }}>
87→        {t('chartRenderError')}: {error}
88→      </div>
89→    );
90→  }
91→
92→  return <div ref={containerRef} style={{ width: '100%', minHeight: 400 }} />;
93→}
