 1→import { useState, useCallback, type ReactNode } from 'react';
 2→import { ChartLibraryContext, type ChartLibrary } from '../hooks/useChartLibrary';
 3→
 4→function getInitialLibrary(): ChartLibrary {
 5→  const stored = localStorage.getItem('chartLibrary');
 6→  if (stored === 'plotly' || stored === 'vegalite') return stored;
 7→  return 'plotly';
 8→}
 9→
10→export function ChartLibraryProvider({ children }: { children: ReactNode }) {
11→  const [chartLibrary, setChartLibraryState] = useState<ChartLibrary>(getInitialLibrary);
12→
13→  const setChartLibrary = useCallback((lib: ChartLibrary) => {
14→    setChartLibraryState(lib);
15→    localStorage.setItem('chartLibrary', lib);
16→  }, []);
17→
18→  return (
19→    <ChartLibraryContext.Provider value={{ chartLibrary, setChartLibrary }}>
20→      {children}
21→    </ChartLibraryContext.Provider>
22→  );
23→}
