 1→import { createContext, useContext } from 'react';
 2→
 3→export type ChartLibrary = 'plotly' | 'vegalite';
 4→
 5→interface ChartLibraryContextValue {
 6→  chartLibrary: ChartLibrary;
 7→  setChartLibrary: (lib: ChartLibrary) => void;
 8→}
 9→
10→export const ChartLibraryContext = createContext<ChartLibraryContextValue>({
11→  chartLibrary: 'plotly',
12→  setChartLibrary: () => {},
13→});
14→
15→export function useChartLibrary() {
16→  return useContext(ChartLibraryContext);
17→}
