13→/**
14→ * Strip chart_spec JSON code blocks from answer text.
15→ * The orchestrator may include the raw chart spec JSON even though the chart
16→ * is rendered separately. Remove ```json ... ``` blocks containing chart_spec
17→ * or Plotly trace data so they don't appear as raw text.
18→ */
19→function stripChartSpecBlocks(text: string): string {
20→  return text.replace(/```(?:json)?\s*\n?\s*\{[\s\S]*?"(?:chart_spec|data)"[\s\S]*?\}\s*\n?\s*```/g, '').trim();
21→}
22→
23→/**
24→ * Fix missing line breaks before bold section headers in text.
25→ * The model sometimes concatenates bold headers directly after the previous
26→ * sentence (e.g. "...for arrays.**Preparing data arrays**"). This inserts
27→ * paragraph breaks so they render on new lines.
28→ */
29→function fixBoldHeaderLineBreaks(text: string): string {
30→  // Insert \n\n before **Header** when preceded by sentence-ending punctuation
31→  // with no whitespace. The [A-Z] ensures we only match section-header-style
32→  // bold (starting with a capital letter), avoiding inline bold like **data**.
33→  return text.replace(/([.!?:])(\*\*[A-Z])/g, '$1\n\n$2');
34→}
35→
36→/** Strip markdown formatting for plain-text preview display. */
37→function stripMarkdown(text: string): string {
38→  return text
39→    .replace(/\*\*(.+?)\*\*/g, '$1')   // **bold**
40→    .replace(/__(.+?)__/g, '$1')        // __bold__
41→    .replace(/\*(.+?)\*/g, '$1')        // *italic*
42→    .replace(/_(.+?)_/g, '$1')          // _italic_
43→    .replace(/`(.+?)`/g, '$1')          // `code`
44→    .replace(/^#+\s+/gm, '');           // # headings
45→}
46→
47→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder: string | undefined, t: (key: string) => string): string {
48→  // Use streaming remainder if available
49→  if (streamingRemainder?.trim()) {
50→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
51→    const last = stripMarkdown(lines[lines.length - 1] || '');
52→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
53→  }
54→  // Otherwise use last thinking segment's last line
55→  for (let i = segments.length - 1; i >= 0; i--) {
56→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
57→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
58→      const last = stripMarkdown(lines[lines.length - 1] || '');
59→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
60→    }
61→  }
62→  return t('thinking');
63→}
64→
65→function ThinkingBlock({ segments, streamingRemainder, isThinkingPhase, isAgentStreaming, hasAnswer }: {
66→  segments: ContentSegment[];
67→  streamingRemainder?: string;
68→  isThinkingPhase: boolean;
69→  isAgentStreaming: boolean;
70→  hasAnswer: boolean;
71→}) {
72→  const { t } = useTranslation();
73→  // All non-answer, non-chart, non-user_question segments go inside the thinking block.
74→  // subagent_end with sqlResults always stays in thinking; text-only subagent_end without
75→  // answer goes to the answer block as a preliminary result.
76→  const thinkingSegments = segments.filter(
77→    (s) => s.type !== 'answer' && s.type !== 'user_question' && !(s.type === 'tool' && s.toolResult?.chart_spec) && !(s.type === 'subagent_end' && (s.chart_spec || (!s.sqlResults?.length && s.text?.trim() && !hasAnswer)))
78→  );
79→  const hasContent = thinkingSegments.some(
80→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult) || s.type === 'subagent_start' || (s.type === 'subagent_end' && !s.chart_spec && (s.text?.trim() || s.sqlResults?.length))

