 8→function CopyButton({ text }: { text: string }) {
 9→  const [copied, setCopied] = useState(false);
10→
11→  const handleCopy = useCallback(async () => {
12→    try {
13→      await navigator.clipboard.writeText(text);
14→      setCopied(true);
15→      setTimeout(() => setCopied(false), 1500);
16→    } catch {
17→      // fallback
18→    }
19→  }, [text]);
20→
21→  return (
22→    <button
23→      className="inline-query__copy-btn"
24→      onClick={handleCopy}
25→      title={copied ? 'Copied!' : 'Copy'}
26→    >
27→      {copied ? (
28→        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
29→          <polyline points="20 6 9 17 4 12" />
