43→function getToolDisplayName(result: ToolCallResult, t: (key: string) => string): string {
44→  const name = result.toolName || '';
45→  if (name.includes('execute_sql')) return t('sqlQuery');
46→  if (name === 'Bash') return t('bash');
47→  if (name === 'Read') return t('readFile');
48→  if (name === 'Write') return t('writeFile');
49→  if (name === 'Edit') return t('editFile');
50→  if (name.startsWith('mcp__')) {
51→    const parts = name.split('__');
52→    return parts[parts.length - 1] || name;
53→  }
54→  return name || 'Tool';
55→}
56→
57→function getToolInputDisplay(result: ToolCallResult): string | null {
58→  if (result.sql) return result.sql;
59→  if (result.command) return result.command;
60→  if (result.toolInput) {
61→    const entries = Object.entries(result.toolInput);
62→    if (entries.length === 0) return null;
63→    // For single-value inputs, show just the value
64→    if (entries.length === 1) {
65→      const val = entries[0][1];
66→      if (val === null || val === undefined) return '';
67→      if (typeof val === 'object') return JSON.stringify(val, null, 2);
68→      return String(val);
69→    }
70→    return JSON.stringify(result.toolInput, null, 2);
71→  }
72→  return null;
73→}
74→
75→function isSQL(result: ToolCallResult): boolean {
76→  return !!result.sql && (result.toolName?.includes('execute_sql') ?? false);
77→}
78→
79→export function InlineQueryResult({ result }: { result: ToolCallResult }) {
80→  const { t } = useTranslation();

 80→  const { t } = useTranslation();
 81→  const displayName = getToolDisplayName(result, t);
 82→  const inputDisplay = getToolInputDisplay(result);
 83→  const isSQLTool = isSQL(result);
 84→  const hasStructuredData = result.columns.length > 0;
 85→  const displayRows = result.rows.slice(0, MAX_DISPLAY_ROWS);
 86→
 87→  // Render chart if chart_spec is present
 88→  if (result.chart_spec) {
 89→    const isVegaLite = result.chart_spec.library === 'vegalite';
 90→    return (
 91→      <div className="inline-query inline-query--chart">
 92→        <div className="inline-query__label inline-query__label--generic">
 93→          {isVegaLite
 94→            ? ((result.chart_spec.spec as Record<string, unknown>)?.title as string) || getToolDisplayName(result, t)
 95→            : (result.chart_spec?.layout?.title as string) || getToolDisplayName(result, t)}
 96→          <CopyButton text={JSON.stringify(isVegaLite ? result.chart_spec.spec : result.chart_spec, null, 2)} />
 97→        </div>
 98→        {isVegaLite ? (
 99→          <VegaLiteChartWidget spec={result.chart_spec.spec!} />
100→        ) : (
101→          <ChartWidget
102→            data={result.chart_spec.data ?? []}
103→            layout={result.chart_spec.layout}
104→            frames={result.chart_spec.frames}
105→          />
106→        )}
107→      </div>
108→    );
109→  }
110→
111→  // Determine border color class
112→  let variantClass = '';
113→  if (result.error) variantClass = 'inline-query--error';
114→  else if (result.command) variantClass = 'inline-query--bash';
115→  else if (!isSQLTool && !result.sql) variantClass = 'inline-query--generic';
116→
117→  return (
118→    <div className={`inline-query ${variantClass}`}>
119→      {/* Tool label */}
120→      <div className={`inline-query__label ${isSQLTool ? 'inline-query__label--sql' : result.command ? 'inline-query__label--bash' : 'inline-query__label--generic'}`}>
121→        {displayName}
122→      </div>
123→
124→      {/* Tool input */}
125→      {inputDisplay && (
126→        <div className="inline-query__sql">
127→          <CopyButton text={inputDisplay} />
128→          <code>{inputDisplay}</code>
129→        </div>
130→      )}
131→
132→      {/* Error display */}
133→      {result.error && (
134→        <div className="inline-query__error">{result.error}</div>
135→      )}
136→
137→      {/* SQL structured results */}
138→      {!result.error && isSQLTool && hasStructuredData && (
139→        <>
140→          <div className="inline-query__table-wrapper">
141→            <table className="inline-query__table">
142→              <thead>
143→                <tr>
144→                  {result.columns.map((col) => (
145→                    <th key={col}>{col}</th>
146→                  ))}
147→                </tr>
148→              </thead>
149→              <tbody>
150→                {displayRows.map((row, i) => (
151→                  <tr key={i}>
152→                    {result.columns.map((col) => (
153→                      <td key={col}>{String(row[col] ?? '')}</td>
154→                    ))}
155→                  </tr>
156→                ))}
157→              </tbody>
158→            </table>
159→          </div>
160→          <div className="inline-query__meta">
161→            {t('rowCount', { count: result.rowCount })}
162→            {result.rowCount > MAX_DISPLAY_ROWS && ` ${t('showingCount', { count: MAX_DISPLAY_ROWS })}`}
163→          </div>
164→        </>
165→      )}
166→
167→      {/* Text output for non-SQL tools */}
168→      {!result.error && result.output && (
169→        <div className="inline-query__output">
170→          <pre>{result.output}</pre>
171→        </div>
172→      )}
173→
174→      {/* Raw content fallback */}
175→      {!result.error && !hasStructuredData && !result.output && result.rawContent && (
176→        <div className="inline-query__raw">
177→          <pre>{result.rawContent}</pre>
178→        </div>
179→      )}
180→
181→      {/* Pending state */}
182→      {!result.error && !hasStructuredData && !result.output && !result.rawContent && inputDisplay && (
183→        <div className="inline-query__meta">{t('executing')}</div>
184→      )}
185→    </div>
186→  );
187→}
