13→interface AgentPanelProps {
14→  tables: TableInfo[];
15→  onUpload: (files: File[]) => Promise<void>;
16→  onLoadSample: () => Promise<void>;
17→  pendingSkillCommand?: string | null;
18→  onSkillCommandConsumed?: () => void;
19→}
